import { seedDemo, generateMonthlyInvoices, recordPartialPayment, submitDemoPayment, decidePayment, requestApproval, decideApproval, updateContact, createStudent, updateFeeRate, addDiscount, verifyReceipt, dashboardTotals, exportRows, periodLabel } from "./core.mjs";

const main = document.querySelector("#main");
const toast = document.querySelector("#toast");
const stateKey = "sasapps-demo-state-v1";
const prefsKey = "sasapps-demo-prefs-v1";
const remoteStorage = window.__SASAPPS_REMOTE__ === true;
let state = readState();
let prefs = readPrefs();
let toastTimer;
let syncTimer;
let serverVersion = null;
let remoteReady = !remoteStorage;
let query = "";
let classFilter = "";
let invoicePeriod = "2026-11";

function readState() {
  try { const raw = localStorage.getItem(stateKey); if (raw) return { ...seedDemo(), ...JSON.parse(raw) }; }
  catch (error) { console.warn("Data demo tidak dapat dibaca dari penyimpanan browser.", error); }
  return seedDemo();
}
function readPrefs() {
  try { return { role: "student", section: "overview", ...JSON.parse(localStorage.getItem(prefsKey) || "{}") }; }
  catch { return { role: "student", section: "overview" }; }
}
function saveLocal() { try { localStorage.setItem(stateKey, JSON.stringify(state)); localStorage.setItem(prefsKey, JSON.stringify(prefs)); } catch { notify("Penyimpanan browser penuh atau dinonaktifkan. Perubahan mungkin tidak tersimpan.", true); } }
function save() {
  saveLocal();
  if (!remoteStorage || !remoteReady) return;
  clearTimeout(syncTimer);
  syncTimer = setTimeout(pushRemoteState, 180);
}
async function loadRemoteState() {
  const response = await fetch("/api/state", { cache: "no-store" });
  if (!response.ok) throw new Error("Database demo tidak merespons.");
  const payload = await response.json();
  if (!payload?.state || !Number.isSafeInteger(payload.version)) throw new Error("Data database demo tidak valid.");
  state = { ...seedDemo(), ...payload.state };
  serverVersion = payload.version;
  remoteReady = true;
  saveLocal();
}
async function pushRemoteState() {
  try {
    const response = await fetch("/api/state", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ version: serverVersion, state }) });
    if (response.status === 409) {
      const latest = await response.json();
      state = { ...seedDemo(), ...latest.state };
      serverVersion = latest.version;
      saveLocal();
      render();
      notify("Data demo berubah di perangkat lain. Muat ulang sebelum mencoba lagi.", true);
      return;
    }
    if (!response.ok) throw new Error("Perubahan belum tersimpan ke database.");
    const result = await response.json();
    serverVersion = result.version;
  } catch {
    notify("Database Render tidak dapat dijangkau. Perubahan ini belum tersimpan bersama.", true);
  }
}
function setState(next) { state = next; save(); render(); }
function notify(message, error = false) { toast.textContent = message; toast.classList.toggle("error", error); toast.classList.add("show"); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove("show"), 3500); }
const money = amount => new Intl.NumberFormat("id-ID", { style: "currency", currency: "IDR", maximumFractionDigits: 0 }).format(Number(amount || 0));
const date = value => new Intl.DateTimeFormat("id-ID", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Jakarta" }).format(new Date(value));
const safe = value => String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
const invoiceBalance = invoice => Math.max(0, invoice.amount - invoice.paid);
const firstStudent = () => state.students[0];
const studentInvoices = () => state.invoices.filter(x => x.studentId === firstStudent().id).sort((a, b) => b.period.localeCompare(a.period));
const statusText = status => ({ paid: "Lunas", unpaid: "Belum lunas", partial: "Parsial", overdue: "Terlambat", pending: "Menunggu verifikasi", verified: "Terverifikasi · demo", rejected: "Ditolak", approved: "Disetujui", partially_approved: "Disetujui sebagian" }[status] || status);
const badge = status => `<span class="status status-${safe(status)}">${safe(statusText(status))}</span>`;

function route() { const value = location.hash.slice(1) || "home"; return value || "home"; }
function updateNav(page) { document.querySelectorAll(".public-nav a").forEach(a => { if (a.dataset.page === page) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current"); }); }
