  if (page === "home") return `${note}<section class="hero"><div class="hero-copy"><div class="eyebrow">${safe(school.name)} · Jakarta</div><h1>Ruang belajar untuk <em>masa depan</em> yang bermakna.</h1><p>Tempat setiap anak menemukan rasa ingin tahu, mengembangkan karakter, dan tumbuh percaya diri bersama komunitas yang peduli.</p><div class="hero-actions"><a class="button" href="#tentang">Kenali sekolah <span aria-hidden="true">→</span></a><a class="button button-light" href="#portal">Jelajahi portal demo</a></div><p class="hero-note">Profil, foto, dan identitas pada situs ini adalah materi placeholder demo.</p></div><div class="hero-art"><div class="campus-card"><img src="https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=1200&q=85" alt="Suasana belajar di ruang kelas, foto ilustrasi"/><div class="campus-caption"><div><strong>Belajar dengan rasa ingin tahu</strong><br/><span>Komunitas ${safe(school.name)}</span></div><span class="gold-mark" aria-hidden="true">✳</span></div></div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Mengenal sekolah</div><h2>Belajar yang dekat<br/>dengan kehidupan.</h2></div><p>Kami percaya pendidikan terbaik memberi ruang untuk bertanya, mencoba, dan menemukan cara anak berkembang dengan caranya sendiri.</p></div><div class="feature-row"><article class="feature"><span class="feature-icon" aria-hidden="true">✦</span><h3>Karakter bertumbuh</h3><p>Nilai saling menghargai, tanggung jawab, dan kepedulian hadir dalam keseharian belajar.</p></article><article class="feature"><span class="feature-icon" aria-hidden="true">⌁</span><h3>Belajar aktif</h3><p>Pengalaman belajar mendorong murid mengamati, berdiskusi, dan berkarya bersama.</p></article><article class="feature"><span class="feature-icon" aria-hidden="true">◎</span><h3>Komunitas peduli</h3><p>Sekolah, murid, dan keluarga tumbuh melalui komunikasi yang terbuka dan saling mendukung.</p></article></div></section><div class="quote-band"><blockquote>“Setiap anak memiliki potensi yang layak mendapat ruang untuk tumbuh.”</blockquote><span>— Nilai pendidikan · contoh narasi demo</span></div><section class="section"><div class="section-head"><div><div class="eyebrow">Kehidupan sekolah</div><h2>Ruang untuk bertumbuh,<br/>di dalam dan di luar kelas.</h2></div><a class="button button-light" href="#fasilitas">Lihat fasilitas →</a></div><div class="facility-grid"><article class="photo-card"><img src="https://images.unsplash.com/photo-1588072432836-e10032774350?auto=format&fit=crop&w=800&q=80" alt="Ilustrasi ruang belajar"><div><h3>Ruang belajar kolaboratif</h3><p>Contoh fasilitas · foto ilustrasi</p></div></article><article class="photo-card"><img src="https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=800&q=80" alt="Ilustrasi kegiatan membaca"><div><h3>Perpustakaan sekolah</h3><p>Contoh fasilitas · foto ilustrasi</p></div></article><article class="photo-card"><img src="https://images.unsplash.com/photo-1475721027785-f74eccf877e2?auto=format&fit=crop&w=800&q=80" alt="Ilustrasi kegiatan siswa"><div><h3>Area berkegiatan</h3><p>Contoh fasilitas · foto ilustrasi</p></div></article></div></section><section class="section section-tight"><div class="section-head"><div><div class="eyebrow">Untuk keluarga sekolah</div><h2>Semua informasi, lebih terhubung.</h2></div><p>Portal demo memperlihatkan bagaimana informasi akademik dan administrasi dapat disajikan dengan lebih jelas.</p></div><div class="action-row"><a href="#portal" class="button">Coba Portal Siswa</a><a href="#kontak" class="button button-light">Hubungi sekolah</a></div></section>`;
  if (page === "tentang") return `<section class="page-hero"><div class="eyebrow">Tentang sekolah</div><h1>Pendidikan yang menguatkan<br/>rasa ingin tahu.</h1><p>Profil contoh Sekolah Swasta Nasional untuk menunjukkan cara sekolah memperkenalkan nilai dan pengalaman belajarnya.</p></section><section class="page-content">${note}<div class="split"><div><div class="eyebrow">Cerita kami</div><h2>Setiap hari adalah kesempatan untuk berkembang.</h2><p>${safe(school.name)} adalah identitas sementara yang digunakan pada demo SASapps. Narasi ini menggambarkan lingkungan belajar yang menghargai keunikan murid, melibatkan keluarga, dan menyediakan pengalaman belajar yang dekat dengan keseharian.</p><p>Nama, sejarah, jenjang, dan klaim tentang sekolah perlu ditinjau serta diganti sebelum website ini dipakai sebagai profil resmi.</p><a class="button" href="#visi">Lihat visi dan misi →</a></div><img src="https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=1000&q=80" alt="Foto ilustrasi suasana belajar"/></div></section>`;
  if (page === "visi") return `<section class="page-hero"><div class="eyebrow">Arah pendidikan</div><h1>Nilai yang menuntun<br/>setiap langkah.</h1><p>Visi dan misi di bawah ini adalah contoh konten yang dapat disesuaikan untuk identitas resmi sekolah.</p></section><section class="page-content">${note}<div class="columns"><article class="panel"><div class="eyebrow">Visi · contoh</div><h2>Menjadi komunitas belajar yang menumbuhkan insan berkarakter, berdaya, dan siap menghadapi perubahan.</h2></article><article class="panel"><div class="eyebrow">Misi · contoh</div><ul class="check-list"><li>Menghadirkan pembelajaran yang aktif dan inklusif.</li><li>Menguatkan nilai integritas, empati, dan tanggung jawab.</li><li>Membangun kemitraan terbuka dengan keluarga.</li><li>Mengembangkan potensi akademik, seni, dan olahraga.</li></ul></article></div></section>`;
  if (page === "fasilitas") return `<section class="page-hero"><div class="eyebrow">Fasilitas belajar</div><h1>Lingkungan yang mendukung<br/>banyak cara belajar.</h1><p>Foto dan daftar berikut adalah ilustrasi, bukan dokumentasi fasilitas aktual.</p></section><section class="page-content">${note}<div class="facility-grid">${[["Ruang kelas", "Pengaturan ruang fleksibel untuk diskusi dan kerja kelompok.", "1588072432836-e10032774350"], ["Perpustakaan", "Area membaca untuk menjelajahi buku, cerita, dan gagasan baru.", "1503676260728-1c00da094a0b"], ["Laboratorium", "Contoh ruang praktik untuk melakukan pengamatan dan percobaan.", "1532094349884-543bc11b234d"], ["Lapangan olahraga", "Ruang untuk bergerak aktif dan belajar bekerja sama.", "1461896836934-ffe607ba8211"], ["Area berkegiatan", "Tempat kegiatan bersama, pertunjukan, dan pameran karya.", "1475721027785-f74eccf877e2"], ["Ruang konseling", "Ruang percakapan yang mendukung kebutuhan murid.", "1529390079861-591de354faf5"]].map(([title, copy, img]) => `<article class="photo-card"><img src="https://images.unsplash.com/photo-${img}?auto=format&fit=crop&w=800&q=80" alt="Ilustrasi ${safe(title.toLowerCase())}"><div><h3>${safe(title)}</h3><p>${safe(copy)} Foto ilustrasi demo.</p></div></article>`).join("")}</div></section>`;
  if (page === "berita") return `<section class="page-hero"><div class="eyebrow">Berita &amp; pengumuman</div><h1>Kabar dari komunitas<br/>sekolah.</h1><p>Contoh berita dan pengumuman untuk kebutuhan presentasi. Tidak mewakili acara aktual.</p></section><section class="page-content">${note}<div class="news-grid">${[["Agenda", "Pekan Apresiasi Karya Murid", "15 November 2026", "1509062522246-3755977927d7"], ["Kegiatan", "Kelas Terbuka: Belajar dari Lingkungan", "8 November 2026", "1503676260728-1c00da094a0b"], ["Pengumuman", "Informasi Kalender Akademik 2026/2027", "1 November 2026", "1588072432836-e10032774350"]].map(([tag, title, day, img]) => `<article class="news-card"><img src="https://images.unsplash.com/photo-${img}?auto=format&fit=crop&w=800&q=80" alt="Ilustrasi ${safe(title)}"><div><time>${safe(day)} · ${safe(tag)}</time><h3>${safe(title)}</h3><p>Informasi contoh untuk menunjukkan tampilan kabar sekolah di website publik.</p></div></article>`).join("")}</div></section>`;
  if (page === "kontak") return `<section class="page-hero"><div class="eyebrow">Hubungi kami</div><h1>Mari berbincang.</h1><p>Informasi kontak di halaman ini adalah placeholder dan bukan kontak sekolah sebenarnya.</p></section><section class="page-content">${note}<div class="columns"><div><h2>${safe(school.name)}</h2><p>${safe(school.address)}</p><p>${safe(school.phone)}<br/>${safe(school.email)}</p><p class="inline-note">Jam layanan contoh: Senin–Jumat, 08.00–15.00 WIB</p></div><form class="panel" data-form="contact-message"><h2>Kirim pertanyaan</h2><div class="field"><label for="contact-name">Nama</label><input id="contact-name" name="name" required maxlength="80" autocomplete="name"></div><div class="field" style="margin-top:.7rem"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" required autocomplete="email"></div><div class="field" style="margin-top:.7rem"><label for="contact-message">Pesan</label><textarea id="contact-message" name="message" required maxlength="500"></textarea></div><p class="inline-note">Form ini hanya menyimpan konfirmasi di browser demo; tidak mengirim ke sekolah.</p><button class="button" type="submit">Kirim pesan demo</button></form></div></section>`;
