function roleLabel(role) { return ({ student: "Siswa", tu: "Tata Usaha", admin: "Super Admin" })[role] || "Demo"; }
function roleMenu() { return `<div class="role-switch" aria-label="Pilih tampilan demo">${[["student", "Siswa"], ["tu", "TU"], ["admin", "Admin"]].map(([r, label]) => `<button type="button" data-role="${r}" aria-pressed="${prefs.role === r}">${label}</button>`).join("")}</div>`; }
function sideNav() {
  const items = prefs.role === "student" ? [["overview", "Ringkasan"], ["invoices", "Tagihan saya"], ["payments", "Riwayat pembayaran"], ["profile", "Profil & kontak"]] : prefs.role === "tu" ? [["overview", "Dashboard"], ["students", "Data siswa"], ["master", "Data master"], ["billing", "Administrasi tagihan"], ["payments", "Verifikasi pembayaran"], ["reports", "Laporan"]] : [["overview", "Ringkasan"], ["approvals", "Persetujuan"], ["settings", "Pengaturan sekolah"], ["audit", "Audit log"]];
  return `<nav class="side-nav" aria-label="Menu ${roleLabel(prefs.role)}"><div class="nav-label">Menu ${roleLabel(prefs.role)}</div>${items.map(([key, label]) => `<button type="button" data-section="${key}" ${prefs.section === key ? 'aria-current="page"' : ""}>${label}</button>`).join("")}<div class="nav-label">Layanan sekolah</div><button type="button" data-page="home">← Website sekolah</button></nav>`;
}
function header(title, subtitle) { return `<div class="portal-top"><div><div class="eyebrow">SASapps · Demo Mode</div><h1>${title}</h1><p>${subtitle}</p></div>${roleMenu()}</div>`; }
function metrics(items) { return `<div class="metrics">${items.map(([label, value, detail, tone]) => `<div class="metric ${tone || ""}"><label>${label}</label><strong>${value}</strong><small>${detail}</small></div>`).join("")}</div>`; }
function barChart() {
  const months = ["2026-06", "2026-07", "2026-08", "2026-09", "2026-10", "2026-11"];
  const vals = months.map(period => state.invoices.filter(x => x.period === period).reduce((sum, x) => sum + x.paid, 0));
  const max = Math.max(...vals, 1);
  return `<div class="chart" aria-label="Grafik pembayaran terverifikasi enam bulan terakhir">${months.map((period, i) => `<div class="chart-col"><span>${money(vals[i]).replace("Rp", "").trim()}</span><div class="chart-bar" style="height:${Math.max(4, Math.round(vals[i] / max * 100))}%" title="${safe(periodLabel(period))}: ${money(vals[i])}"></div><small>${period.slice(5)}</small></div>`).join("")}</div><p class="chart-caption">Nilai berasal dari data simulasi yang sudah dicatat pada demo ini.</p>`;
}
function invoiceRows(items) {
  if (!items.length) return `<div class="empty-state"><strong>Belum ada tagihan di periode ini.</strong>Gunakan tombol Buat tagihan demo untuk menambahkan contoh data.</div>`;
  return `<div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Kelas</th><th>Periode</th><th>Nominal</th><th>Dibayar</th><th>Sisa</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x => `<tr><td><strong>${safe(x.studentName)}</strong><br><span class="inline-note">${safe(x.nis)}</span></td><td>${safe(x.className)}</td><td>${safe(periodLabel(x.period))}</td><td>${money(x.amount)}</td><td>${money(x.paid)}</td><td><strong>${money(invoiceBalance(x))}</strong></td><td>${badge(x.status)}</td><td><button class="button button-light button-small" type="button" data-action="preview-invoice" data-id="${safe(x.id)}">Detail</button></td></tr>`).join("")}</tbody></table></div>`;
}
function studentOverview() {
  const student = firstStudent(); const invoices = studentInvoices(); const current = invoices.find(x => x.period === "2026-11");
  const pending = state.payments.filter(x => x.studentId === student.id && x.status === "pending").length;
  return `<div class="demo-warning"><span aria-hidden="true">ⓘ</span><div><strong>Simulasi siswa — ${safe(student.name)}.</strong> Perpindahan peran tidak mengamankan data seperti login sungguhan. Jangan masukkan data pribadi nyata.</div></div>${metrics([["Tagihan November", current ? money(current.amount) : "—", current ? statusText(current.status) : "Tidak ada tagihan", "teal"], ["Sisa tagihan", current ? money(invoiceBalance(current)) : money(0), "Periode berjalan · demo", "gold"], ["Pembayaran menunggu", String(pending), "Perlu verifikasi TU", "blue"], ["Tahun ajaran", student.year, student.className, ""]])}<div class="columns"><section class="panel"><h2>Tagihan terbaru</h2><p class="panel-subtitle">Rincian biaya sekolah fiktif untuk akun demo.</p>${invoices.slice(0, 3).map(x => `<div class="invoice-card"><div><strong>${safe(periodLabel(x.period))} · SPP</strong><p>Jatuh tempo ${safe(date(`${x.dueDate}T12:00:00+07:00`))} · ${badge(x.status)}</p></div><div class="invoice-total"><b>${money(x.amount)}</b><span class="inline-note">Sisa ${money(invoiceBalance(x))}</span></div><div class="action-row"><button type="button" class="button button-light button-small" data-action="preview-invoice" data-id="${safe(x.id)}">Lihat detail</button>${invoiceBalance(x) > 0 ? `<button type="button" class="button button-small" data-action="pay-invoice" data-id="${safe(x.id)}">Catat pembayaran demo</button>` : ""}</div></div>`).join("")}</section><section class="panel"><h2>Profil siswa</h2><div class="student-card"><span class="avatar" aria-hidden="true">${safe(student.name.split(" ").map(x => x[0]).slice(0, 2).join(""))}</span><div><h3>${safe(student.name)}</h3><p>NIS ${safe(student.nis)} · ${safe(student.className)}</p><p>Status ${safe(student.status)} · Tahun ${safe(student.year)}</p></div></div><hr style="border:0;border-top:1px solid var(--line);margin:1rem 0"><h3>Kontak demo</h3><p class="inline-note">${safe(state.contact.email)}<br>${safe(state.contact.phone)}</p><button type="button" class="button button-light button-small" data-section="profile">Kelola kontak</button><p class="inline-note" style="margin-top:.8rem">${state.receipts.length} kuitansi demo tersedia</p></section></div>`;
}
function studentInvoicesView() { return `<section class="panel"><h2>Tagihan per periode</h2><p class="panel-subtitle">Detail komponen dan status dapat dicetak sebagai invoice demo.</p>${studentInvoices().map(x => `<div class="invoice-card"><div><strong>${safe(periodLabel(x.period))} · ${safe(x.lines.map(l => l.label).join(", "))}</strong><p>Jatuh tempo ${safe(date(`${x.dueDate}T12:00:00+07:00`))} · ${badge(x.status)}</p><p>${money(x.paid)} dibayarkan dari ${money(x.amount)}</p></div><div class="invoice-total"><b>Sisa ${money(invoiceBalance(x))}</b><button class="button button-light button-small" type="button" data-action="preview-invoice" data-id="${safe(x.id)}">Cetak preview</button></div>${invoiceBalance(x) > 0 ? `<button class="button button-small" type="button" data-action="pay-invoice" data-id="${safe(x.id)}">Catat pembayaran demo</button>` : ""}</div>`).join("")}</section>`; }
function paymentsView() { const payments = state.payments.filter(x => prefs.role !== "student" || x.studentId === firstStudent().id); return `<section class="panel"><h2>Riwayat pembayaran</h2><p class="panel-subtitle">Pembayaran fiktif tidak memindahkan uang dan tidak membuktikan transaksi bank.</p>${payments.length ? `<div class="table-wrap"><table><thead><tr><th>Tanggal</th>${prefs.role === "student" ? "" : "<th>Siswa</th>"}<th>Nominal</th><th>Metode demo</th><th>Status</th><th></th></tr></thead><tbody>${payments.map(x => `<tr><td>${safe(date(x.createdAt))}</td>${prefs.role === "student" ? "" : `<td>${safe(x.studentName)}</td>`}<td><strong>${money(x.amount)}</strong></td><td>${safe(x.method)}</td><td>${badge(x.status)}</td><td>${x.status === "verified" ? `<button class="button button-light button-small" data-action="receipt" data-id="${safe(x.id)}">Kuitansi</button>` : safe(x.note)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty-state"><strong>Belum ada pembayaran.</strong>Catatan pembayaran demo akan terlihat di sini.</div>`}</section>`; }
function profileView() { const s = firstStudent(); return `<section class="panel"><h2>Profil siswa</h2><div class="student-card"><span class="avatar">${safe(s.name.split(" ").map(x => x[0]).slice(0, 2).join(""))}</span><div><h3>${safe(s.name)}</h3><p>NIS ${safe(s.nis)} · ${safe(s.className)} · Tahun ${safe(s.year)}</p><p>Status ${safe(s.status)}</p></div></div></section><section class="panel"><h2>Perbarui kontak demo</h2><p class="panel-subtitle">Permintaan ini hanya mengubah data di penyimpanan browser Anda.</p><form class="form-grid" data-form="student-contact"><div class="field"><label for="student-email">Email</label><input id="student-email" name="email" type="email" required value="${safe(state.contact.email)}"></div><div class="field"><label for="student-phone">Nomor kontak</label><input id="student-phone" name="phone" required value="${safe(state.contact.phone)}"></div><div class="field full"><button class="button" type="submit">Simpan kontak demo</button></div></form></section>`; }
function tuOverview() { const totals = dashboardTotals(state); const periodInvoices = state.invoices.filter(x => x.period === invoicePeriod); return `<div class="demo-warning"><span aria-hidden="true">ⓘ</span><div><strong>Dashboard Tata Usaha · data sintetis.</strong> Angka dan grafik menunjukkan contoh catatan demo, bukan laporan keuangan sekolah.</div></div>${metrics([["Siswa aktif", totals.activeStudents, "20 akun fiktif", "teal"], ["Tagihan berjalan", money(totals.billed), periodLabel(invoicePeriod), "gold"], ["Pembayaran tercatat", money(totals.verified), "Nilai pada data demo", "blue"], ["Total tunggakan", money(totals.outstanding), "Dihitung dari sisa tagihan", "red"], ["Menunggu verifikasi", totals.pendingPayments, "Pembayaran demo", ""], ["Menunggu persetujuan", totals.pendingApprovals, "Perubahan demo", ""]])}<div class="columns"><section class="panel"><h2>Tren pembayaran</h2>${barChart()}</section><section class="panel"><h2>Perhatian hari ini</h2><p>${totals.pendingPayments} pembayaran demo membutuhkan keputusan.</p><p>${totals.pendingApprovals} permintaan menunggu persetujuan Admin.</p><div class="action-row"><button class="button button-light button-small" data-section="payments">Buka antrean pembayaran</button><button class="button button-light button-small" data-role="admin" data-section="approvals">Buka approval</button></div></section></div><section class="panel"><h2>Ringkasan tagihan · ${safe(periodLabel(invoicePeriod))}</h2>${invoiceRows(periodInvoices.slice(0, 6))}<div class="action-row"><button class="button button-light button-small" data-section="billing">Kelola tagihan</button></div></section>`; }
function studentsView() { const items = state.students.filter(x => `${x.name} ${x.nis} ${x.className}`.toLowerCase().includes(query.toLowerCase()) && (!classFilter || x.className === classFilter)); const classes = Object.keys(state.classRates || {}); return `<section class="panel"><h2>Tambah siswa demo</h2><p class="panel-subtitle">Gunakan nama dan NIS sintetis saja.</p><form class="form-grid" data-form="create-student"><label class="field"><span>Nama siswa</span><input name="name" required maxlength="80" minlength="3"></label><label class="field"><span>NIS demo · 6–12 angka</span><input name="nis" required pattern="[0-9]{6,12}" inputmode="numeric"></label><label class="field"><span>Kelas</span><select name="className" required>${classes.map(x => `<option value="${safe(x)}">${safe(x)}</option>`).join("")}</select></label><div class="field"><span>&nbsp;</span><button class="button" type="submit">Tambah siswa fiktif</button></div></form></section><section class="panel"><h2>Data siswa</h2><p class="panel-subtitle">Daftar sintetis dengan pencarian kelas, nama, dan NIS.</p><div class="toolbar"><div class="field"><label for="student-search">Cari siswa</label><input id="student-search" type="search" placeholder="Nama, NIS, atau kelas" value="${safe(query)}"></div><label class="field"><span>Filter kelas</span><select id="class-filter"><option value="">Semua kelas</option>${[...new Set(state.students.map(x => x.className))].map(x => `<option value="${safe(x)}" ${classFilter === x ? "selected" : ""}>${safe(x)}</option>`).join("")}</select></label><span class="pill">${items.length} siswa ditemukan</span></div><div class="table-wrap"><table><thead><tr><th>NIS</th><th>Nama</th><th>Kelas</th><th>Tahun ajaran</th><th>Status</th><th>Sisa November</th></tr></thead><tbody>${items.map(s => { const inv = state.invoices.find(x => x.studentId === s.id && x.period === "2026-11"); return `<tr><td>${safe(s.nis)}</td><td><strong>${safe(s.name)}</strong></td><td>${safe(s.className)}</td><td>${safe(s.year)}</td><td><span class="status status-paid">${safe(s.status)}</span></td><td>${money(inv ? invoiceBalance(inv) : 0)}</td></tr>`; }).join("")}</tbody></table></div></section>`; }
function masterDataView() { const classes = Object.entries(state.classRates || {}); return `<div class="demo-warning"><span>ⓘ</span><div><strong>Data master demo.</strong> Perubahan tarif memengaruhi tagihan yang baru dibuat, tidak menulis ulang invoice yang sudah ada.</div></div><section class="panel"><h2>Tahun ajaran &amp; kelas</h2><p>Tahun ajaran aktif: <strong>${safe(state.school.academicYear || "2026/2027")}</strong></p><div class="table-wrap"><table><thead><tr><th>Kelas</th><th>Jenjang</th><th>Tarif SPP (IDR)</th><th>Contoh penyesuaian</th></tr></thead><tbody>${classes.map(([name, rate]) => `<tr><td><strong>${safe(name)}</strong></td><td>${safe(name.split("-")[0])}</td><td>${money(rate)}</td><td>${(state.discounts || []).filter(x => x.className === name).map(x => `${safe(x.label)} · ${money(x.amount)}`).join("; ") || "—"}</td></tr>`).join("")}</tbody></table></div><p class="inline-note">Jenis biaya demo: ${(state.feeTypes || []).map(safe).join(", ")}. Perubahan tarif dan beasiswa tercatat di audit log browser.</p></section><div class="columns"><section class="panel"><h2>Perbarui tarif kelas</h2><form class="form-grid" data-form="fee-rate"><label class="field"><span>Kelas</span><select name="className">${classes.map(([name]) => `<option value="${safe(name)}">${safe(name)}</option>`).join("")}</select></label><label class="field"><span>Tarif SPP (IDR)</span><input name="amount" type="number" min="0" max="100000000" step="1000" required></label><div class="field full"><button class="button" type="submit">Simpan tarif demo</button></div></form></section><section class="panel"><h2>Tambah beasiswa / diskon</h2><form class="form-grid" data-form="discount"><label class="field"><span>Nama penyesuaian</span><input name="label" required maxlength="80" placeholder="Beasiswa Contoh"></label><label class="field"><span>Kelas</span><select name="className">${classes.map(([name]) => `<option value="${safe(name)}">${safe(name)}</option>`).join("")}</select></label><label class="field"><span>Nominal (IDR)</span><input name="amount" type="number" min="1000" step="1000" required></label><div class="field"><span>&nbsp;</span><button class="button" type="submit">Tambah penyesuaian demo</button></div></form></section></div>`; }
function billingView() { const items = state.invoices.filter(x => x.period === invoicePeriod); return `<section class="panel"><h2>Administrasi tagihan</h2><p class="panel-subtitle">Invoice demo per siswa dengan rincian biaya dan tanggal jatuh tempo.</p><div class="toolbar"><label class="field"><span>Periode tagihan</span><select id="period-select">${[...new Set([...state.invoices.map(x => x.period), "2026-12"])].sort().reverse().map(x => `<option value="${safe(x)}" ${invoicePeriod === x ? "selected" : ""}>${safe(periodLabel(x))}</option>`).join("")}</select></label><button class="button" data-action="generate-invoices">Buat tagihan demo</button><button class="button button-light" data-action="download-csv">Ekspor CSV</button></div>${invoiceRows(items)}</section><div class="columns"><section class="panel"><h2>Catat pembayaran parsial</h2><p class="panel-subtitle">Dicatat sebagai terverifikasi secara simulasi; tidak menerima uang sungguhan.</p><form class="form-grid" data-form="partial-payment"><label class="field full"><span>Pilih tagihan</span><select name="invoiceId" required>${state.invoices.filter(x => invoiceBalance(x) > 0).map(x => `<option value="${safe(x.id)}">${safe(x.studentName)} · ${safe(periodLabel(x.period))} · sisa ${money(invoiceBalance(x))}</option>`).join("")}</select></label><label class="field"><span>Nominal (IDR)</span><input name="amount" type="number" min="1000" step="1000" required></label><label class="field"><span>Catatan</span><input name="note" maxlength="120" value="Pembayaran parsial demo"></label><div class="field full"><button class="button" type="submit">Simpan pembayaran demo</button></div></form></section><section class="panel"><h2>Usulkan perubahan tagihan</h2><p class="panel-subtitle">Perubahan menunggu keputusan Super Admin demo.</p><form class="form-grid" data-form="approval-request"><label class="field full"><span>Tagihan yang diubah</span><select name="invoiceId" required>${state.invoices.filter(x => x.period === invoicePeriod).map(x => `<option value="${safe(x.id)}">${safe(x.studentName)} · ${safe(periodLabel(x.period))}</option>`).join("")}</select></label><label class="field"><span>Nominal usulan</span><input name="amount" type="number" min="0" step="1000" required></label><label class="field"><span>Alasan</span><input name="reason" required maxlength="180" placeholder="Alasan perubahan"></label><div class="field full"><button class="button" type="submit">Kirim permintaan approval</button></div></form></section></div>`; }
function paymentQueue() { const pending = state.payments.filter(x => x.status === "pending"); return `<section class="panel"><h2>Antrean verifikasi pembayaran</h2><p class="panel-subtitle">Verifikasi demo memperbarui sisa tagihan dan membuat kuitansi simulasi.</p>${pending.length ? pending.map(x => `<article class="approval-card"><header><div><strong>${safe(x.studentName)}</strong><p>${safe(date(x.createdAt))} · ${safe(x.method)} · ${money(x.amount)}</p><p>${safe(x.note)}</p></div>${badge(x.status)}</header><div class="action-row"><button class="button button-small" data-action="decide-payment" data-id="${safe(x.id)}" data-status="verified">Verifikasi demo</button><button class="button button-danger button-small" data-action="decide-payment" data-id="${safe(x.id)}" data-status="rejected">Tolak</button></div></article>`).join("") : `<div class="empty-state"><strong>Antrean kosong.</strong>Tidak ada pembayaran demo yang menunggu verifikasi.</div>`}</section>${paymentsView()}`; }
function reportsView() { const byPeriod = [...new Set(state.invoices.map(x => x.period))].sort().reverse().map(period => { const list = state.invoices.filter(x => x.period === period); return { period, count: list.length, billed: list.reduce((s, x) => s + x.amount, 0), paid: list.reduce((s, x) => s + x.paid, 0), due: list.reduce((s, x) => s + invoiceBalance(x), 0) }; }); return `<section class="panel"><h2>Laporan demo</h2><p class="panel-subtitle">Ringkasan bulanan direkonsiliasi dari invoice dan pembayaran contoh.</p><div class="toolbar"><button class="button" data-action="download-csv">Unduh CSV</button><span class="pill">${state.invoices.length} baris tagihan</span></div><div class="table-wrap"><table><thead><tr><th>Periode</th><th>Jumlah siswa</th><th>Tagihan</th><th>Terbayar</th><th>Tunggakan</th></tr></thead><tbody>${byPeriod.map(x => `<tr><td>${safe(periodLabel(x.period))}</td><td>${x.count}</td><td>${money(x.billed)}</td><td>${money(x.paid)}</td><td>${money(x.due)}</td></tr>`).join("")}</tbody></table></div><p class="inline-note">Ekspor CSV memakai data demo di browser ini. Tidak ada data yang dikirim ke server.</p></section>`; }
function approvalList() { const approvals = state.approvals; return `<section class="panel"><h2>Permintaan persetujuan</h2><p class="panel-subtitle">Tinjau perubahan sebelum/sesudah. Partial approve mencatat field yang diterima dan ditolak.</p>${approvals.length ? approvals.map(a => { const accepted = a.acceptedFields || []; const denied = ["amount", "dueDate"].filter(x => !accepted.includes(x)); return `<article class="approval-card"><header><div><strong>${safe(a.type)} · ${safe(a.studentName)}</strong><p>${safe(periodLabel(a.period))} · diajukan oleh ${safe(a.requestedBy)}</p></div>${badge(a.status)}</header><div class="diff"><div><b>Nominal · sebelum</b>${money(a.before.amount)}</div><div><b>Nominal · usulan</b>${money(a.proposed.amount)}</div><div><b>Jatuh tempo · sebelum</b>${safe(a.before.dueDate || "—")}</div><div><b>Jatuh tempo · usulan</b>${safe(a.proposed.dueDate || "—")}</div><div><b>Alasan TU</b>${safe(a.reason)}</div><div><b>Hasil keputusan</b>Diterima: ${safe(accepted.join(", ") || "belum diputuskan")}; ditolak: ${safe(denied.join(", ") || "tidak ada")}</div></div>${a.status === "pending" ? `<div class="action-row"><button class="button button-small" data-action="decide-approval" data-id="${safe(a.id)}" data-decision="approve">Setujui semua</button><button class="button button-light button-small" data-action="decide-approval" data-id="${safe(a.id)}" data-decision="partial">Setujui sebagian</button><button class="button button-danger button-small" data-action="decide-approval" data-id="${safe(a.id)}" data-decision="reject">Tolak semua</button></div>` : `<p class="inline-note">Keputusan: ${safe(a.reviewReason || "—")}</p>`}</article>`; }).join("") : `<div class="empty-state"><strong>Belum ada permintaan.</strong>Permintaan baru dari Tata Usaha akan muncul di sini.</div>`}</section>`; }
function settingsView() { return `<section class="panel"><h2>Identitas &amp; branding</h2><p class="panel-subtitle">Konten berikut adalah placeholder yang dapat diatur melalui tampilan Admin demo.</p><form class="school-settings" data-form="school-settings"><label class="field"><span>Nama sekolah</span><input name="name" required maxlength="100" value="${safe(state.school.name)}"></label><label class="field"><span>Slogan</span><input name="tagline" maxlength="140" value="${safe(state.school.tagline)}"></label><label class="field"><span>Alamat placeholder</span><input name="address" maxlength="180" value="${safe(state.school.address)}"></label><label class="field"><span>Email placeholder</span><input name="email" type="email" value="${safe(state.school.email)}"></label><label class="field"><span>Telepon placeholder</span><input name="phone" maxlength="30" value="${safe(state.school.phone)}"></label><label class="field"><span>Tahun ajaran aktif</span><input name="academicYear" maxlength="20" value="${safe(state.school.academicYear || "2026/2027")}"></label><div class="field"><span>Logo demo</span><div class="pill">Perisai SASapps · SVG orisinal placeholder</div></div><div class="field full"><button class="button" type="submit">Simpan pengaturan demo</button></div></form></section><section class="panel"><h2>Role simulasi &amp; batas demo</h2><div class="demo-warning"><span aria-hidden="true">ⓘ</span><div><strong>Role switcher bukan autentikasi.</strong> Aplikasi ini tidak memiliki akun, password, atau kontrol akses server-side. Jangan menggunakannya untuk data nyata.</div></div><p class="security-copy">Admin Demo · TU Demo · Siswa Demo merupakan tampilan simulasi pada browser yang sama. Data disimpan di local storage browser Anda. Reset Demo Data menghapus perubahan di browser ini saja.</p><button type="button" class="button button-danger" data-action="reset-demo">Reset Demo Data</button></section>`; }
function auditView() { const events = [...state.audit].reverse(); return `<section class="panel"><h2>Audit log demo</h2><p class="panel-subtitle">Histori simulasi yang tersimpan pada browser aktif.</p>${events.length ? `<ul class="audit-list">${events.map(x => `<li><time>${safe(date(x.at))} · ${safe(x.actor)}</time><span><strong>${safe(x.action.replaceAll("_", " "))}</strong><br>${safe(x.detail)}</span></li>`).join("")}</ul>` : `<div class="empty-state"><strong>Belum ada aktivitas.</strong>Aksi demo akan tercatat di sini.</div>`}</section>`; }
function studentSection() { return ({ overview: studentOverview, invoices: studentInvoicesView, payments: paymentsView, profile: profileView })[prefs.section]?.() || studentOverview(); }
function tuSection() { return ({ overview: tuOverview, students: studentsView, master: masterDataView, billing: billingView, payments: paymentQueue, reports: reportsView })[prefs.section]?.() || tuOverview(); }
function adminSection() { const sections = { overview: () => `${metrics([["Siswa fiktif", state.students.length, "Data demo", "teal"], ["Permintaan pending", state.approvals.filter(x => x.status === "pending").length, "Perlu ditinjau", "gold"], ["Audit events", state.audit.length, "Riwayat lokal browser", "blue"], ["Integrasi produksi", "Belum aktif", "Demo pribadi", ""]])}<div class="columns"><section class="panel"><h2>Persetujuan menunggu</h2>${state.approvals.filter(x => x.status === "pending").length ? `<p>${state.approvals.filter(x => x.status === "pending").length} permintaan membutuhkan keputusan.</p><button class="button button-light button-small" data-section="approvals">Tinjau permintaan</button>` : `<div class="empty-state"><strong>Tidak ada permintaan pending.</strong></div>`}</section><section class="panel"><h2>Keamanan demo</h2><p class="security-copy">Belum ada autentikasi, database server, atau integrasi pembayaran. Seluruh perubahan data tersimpan pada local storage browser.</p></section></div>`, approvals: approvalList, settings: settingsView, audit: auditView }; return (sections[prefs.section] || sections.overview)(); }
function portal() {
  const title = prefs.role === "student" ? "Halo, Alya 👋" : prefs.role === "tu" ? "Dashboard Tata Usaha" : "Super Admin";
  const subtitle = prefs.role === "student" ? "Berikut ringkasan informasi sekolah dan tagihan Anda." : prefs.role === "tu" ? "Pantau data operasional dan transaksi demo." : "Atur identitas demo dan tinjau aktivitas administrasi.";
  return `<div class="portal-shell">${header(title, subtitle)}<div class="demo-warning"><span aria-hidden="true">ⓘ</span><div><strong>Aplikasi demo pribadi · tidak untuk operasional sekolah.</strong> Role dapat diganti tanpa login dan semua perubahan hanya tersimpan pada browser ini.</div></div><div class="portal-layout">${sideNav()}<div class="portal-content">${prefs.role === "student" ? studentSection() : prefs.role === "tu" ? tuSection() : adminSection()}</div></div></div>`;
}
function receiptPage(code) {
  const result = verifyReceipt(state, code);
  return `<section class="page-hero"><div class="eyebrow">Verifikasi kuitansi demo</div><h1>${result.valid ? "Status kuitansi tercatat." : "Kuitansi tidak ditemukan."}</h1><p>Verifikasi ini membaca data sintetis yang tersimpan di browser ini. Kode QR dan status di sini bukan bukti pembayaran sah.</p></section><section class="page-content"><div class="demo-warning"><span aria-hidden="true">ⓘ</span><div><strong>Simulasi verifikasi, bukan validasi server.</strong> Hasil dapat berbeda di browser lain karena data demo disimpan secara lokal.</div></div><div class="panel" style="max-width:560px"><h2>${result.valid ? "Kuitansi demo ditemukan" : "Kode tidak dikenal"}</h2>${result.valid ? `<p>Nomor kuitansi: <strong>${safe(result.receiptNumber)}</strong></p><p>Nilai simulasi: <strong>${money(result.amount)}</strong></p><p>Status: ${badge("verified")}</p><p class="inline-note">Waktu pencatatan ${safe(date(result.issuedAt))} · nama siswa tidak ditampilkan</p>` : `<p>Pastikan kode verifikasi berasal dari kuitansi demo yang tersimpan pada browser ini.</p>`}<a class="button button-light" href="#portal">Kembali ke SASapps</a></div></section>`;
}
function render() {
  const page = route();
  if (page === "portal") updateNav("portal"); else updateNav(page);
  const verify = new URLSearchParams(location.search).get("verify");
  main.innerHTML = verify ? receiptPage(verify) : publicPage(page);
  document.title = verify ? "Verifikasi Kuitansi Demo · SASapps" : `${({ home: "Beranda", tentang: "Tentang Sekolah", visi: "Visi & Misi", fasilitas: "Fasilitas", berita: "Berita", kontak: "Kontak", portal: "Portal Demo" })[page] || "Halaman"} · SASapps`;
}

function downloadCsv() {
  const rows = exportRows(state);
  const csv = [Object.keys(rows[0] || { nis: "", siswa: "" }).join(","), ...rows.map(row => Object.values(row).map(value => `"${String(value).replaceAll('"', '""')}"`).join(","))].join("\r\n");
  const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8" })); link.download = `laporan-sasapps-demo-${invoicePeriod}.csv`; link.click(); URL.revokeObjectURL(link.href); notify("CSV demo berhasil dibuat.");
}
function showReceipt(paymentId) {
  const receipt = state.receipts.find(x => x.paymentId === paymentId);
  if (!receipt) return notify("Kuitansi hanya tersedia untuk pembayaran yang terverifikasi demo.", true);
  const url = `${location.origin}${location.pathname}?verify=${encodeURIComponent(receipt.code)}#beranda`;
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(url)}`;
  openModal("Kuitansi demo", `<div class="receipt"><div><strong>${safe(state.school.name)} · placeholder</strong><p>Nomor: <span class="receipt-code">${safe(receipt.code)}</span></p><p>Nilai simulasi: <strong>${money(receipt.amount)}</strong></p><p>Status: ${badge("verified")}</p><p class="inline-note">Dicatat ${safe(date(receipt.issuedAt))}</p></div><div class="qr"><img src="${qrUrl}" alt="QR demo untuk membuka verifikasi kuitansi"></div></div><div class="demo-warning" style="margin-top:.8rem"><span>ⓘ</span><div><strong>Bukan bukti pembayaran sah.</strong>QR memuat URL verifikasi dengan nomor kuitansi demo; halaman verifikasi tidak menampilkan nama siswa.</div></div><div class="action-row"><a class="button button-light" href="${safe(url)}" target="_blank" rel="noopener">Buka verifikasi</a><button type="button" class="button" data-action="print-receipt">Cetak kuitansi demo</button></div>`);
}
function previewInvoice(id) {
  const invoice = state.invoices.find(x => x.id === id); if (!invoice) return;
  const content = `<section class="panel"><h2>Invoice Demo · ${safe(periodLabel(invoice.period))}</h2><p><strong>${safe(invoice.studentName)}</strong> · NIS ${safe(invoice.nis)} · ${safe(invoice.className)}</p><div class="table-wrap"><table><thead><tr><th>Komponen</th><th>Nominal</th></tr></thead><tbody>${invoice.lines.map(line => `<tr><td>${safe(line.label)}</td><td>${money(line.amount)}</td></tr>`).join("")}<tr><td>Total tagihan</td><td><strong>${money(invoice.amount)}</strong></td></tr><tr><td>Sudah dibayar</td><td>${money(invoice.paid)}</td></tr><tr><td>Sisa</td><td><strong>${money(invoiceBalance(invoice))}</strong></td></tr></tbody></table></div><p>Jatuh tempo ${safe(date(`${invoice.dueDate}T12:00:00+07:00`))} · ${badge(invoice.status)}</p><div class="demo-warning">Invoice ini adalah data sintetis untuk demo.</div><button class="button button-light" onclick="window.print()">Cetak preview</button></section>`;
  main.insertAdjacentHTML("afterbegin", `<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="invoice-title"><button class="modal-close" type="button" aria-label="Tutup detail" data-action="close-modal">×</button><div id="invoice-title">${content}</div></section></div>`);
  document.querySelector(".modal-close")?.focus();
}
function openModal(title, body) {
  document.querySelector(".modal-backdrop")?.remove();
  main.insertAdjacentHTML("afterbegin", `<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><button class="modal-close" type="button" aria-label="Tutup" data-action="close-modal">×</button><div class="modal-body"><p class="eyebrow">SASapps · Demo Mode</p><h2>${safe(title)}</h2>${body}</div></section></div>`);
  document.querySelector(".modal-close")?.focus();
}

document.addEventListener("click", event => {
  const pageLink = event.target.closest("[data-page]");
  if (pageLink) { event.preventDefault(); location.hash = pageLink.dataset.page; document.querySelector(".public-nav")?.classList.remove("open"); document.querySelector(".menu-toggle")?.setAttribute("aria-expanded", "false"); return; }
  const role = event.target.closest("[data-role]");
  if (role) { prefs.role = role.dataset.role; prefs.section = role.dataset.section || "overview"; query = ""; save(); render(); return; }
  const section = event.target.closest("[data-section]");
  if (section) { prefs.section = section.dataset.section; save(); render(); return; }
  const action = event.target.closest("[data-action]"); if (!action) return;
  try {
    if (action.dataset.action === "generate-invoices") { setState(generateMonthlyInvoices(state, invoicePeriod)); notify("Tagihan periode demo berhasil dibuat."); }
    if (action.dataset.action === "partial-payment") { }
    if (action.dataset.action === "download-csv") downloadCsv();
    if (action.dataset.action === "preview-invoice") previewInvoice(action.dataset.id);
    if (action.dataset.action === "close-modal") document.querySelector(".modal-backdrop")?.remove();
    if (action.dataset.action === "receipt") showReceipt(action.dataset.id);
    if (action.dataset.action === "pay-invoice") { const invoice = state.invoices.find(x => x.id === action.dataset.id); openModal("Catat pembayaran simulasi", `<p>Tagihan ${safe(invoice.studentName)} · ${safe(periodLabel(invoice.period))}. Sisa ${money(invoiceBalance(invoice))}.</p><div class="demo-warning"><span>ⓘ</span><div>Catatan ini fiktif, menunggu verifikasi TU, dan tidak memindahkan uang.</div></div><form class="form-grid" data-form="student-payment"><input type="hidden" name="invoiceId" value="${safe(invoice.id)}"><label class="field full"><span>Nominal simulasi (IDR)</span><input type="number" name="amount" min="1000" max="${invoiceBalance(invoice)}" step="1000" value="${Math.min(invoiceBalance(invoice), 250000)}" required></label><label class="field full"><span>Catatan</span><input name="note" maxlength="120" value="Pembayaran fiktif menunggu verifikasi"></label><div class="field full"><button class="button" type="submit">Kirim untuk verifikasi demo</button></div></form>`); }
    if (action.dataset.action === "decide-payment") { const payment = state.payments.find(x => x.id === action.dataset.id); const decision = action.dataset.status; openModal(decision === "verified" ? "Verifikasi pembayaran demo" : "Tolak pembayaran demo", `<p>${safe(payment.studentName)} · ${money(payment.amount)}.</p><form class="form-grid" data-form="payment-decision"><input type="hidden" name="paymentId" value="${safe(payment.id)}"><input type="hidden" name="decision" value="${safe(decision)}"><label class="field full"><span>Alasan atau catatan keputusan</span><textarea name="reason" required maxlength="200">${decision === "verified" ? "Data pembayaran demo cocok." : "Data simulasi tidak cocok."}</textarea></label><div class="field full"><button class="button ${decision === "rejected" ? "button-danger" : ""}" type="submit">Simpan keputusan demo</button></div></form>`); }
    if (action.dataset.action === "decide-approval") { const request = state.approvals.find(x => x.id === action.dataset.id); const decision = action.dataset.decision; openModal("Tinjau perubahan tagihan", `<p><strong>${safe(request.studentName)} · ${safe(periodLabel(request.period))}</strong></p><div class="diff"><div><b>Nominal sebelum</b>${money(request.before.amount)}</div><div><b>Nominal usulan</b>${money(request.proposed.amount)}</div><div><b>Jatuh tempo sebelum</b>${safe(request.before.dueDate || "—")}</div><div><b>Jatuh tempo usulan</b>${safe(request.proposed.dueDate || "—")}</div></div><p class="inline-note">Alasan TU: ${safe(request.reason)}</p><form class="form-grid" data-form="approval-decision"><input type="hidden" name="requestId" value="${safe(request.id)}"><input type="hidden" name="decision" value="${safe(decision)}">${decision === "partial" ? `<fieldset class="field full"><legend>Pilih bagian yang diterima</legend><label><input type="checkbox" name="fields" value="amount" checked> Nominal ${money(request.proposed.amount)}</label><br><label><input type="checkbox" name="fields" value="dueDate" ${request.proposed.dueDate ? "checked" : "disabled"}> Jatuh tempo ${safe(request.proposed.dueDate || "belum diusulkan")}</label><p class="inline-note">Bagian yang tidak dipilih akan ditolak.</p></fieldset>` : ""}<label class="field full"><span>Alasan keputusan Admin (wajib)</span><textarea name="reason" required maxlength="200">${decision === "reject" ? "Perubahan tidak disetujui." : "Ditinjau oleh Admin Demo."}</textarea></label><div class="field full"><button class="button ${decision === "reject" ? "button-danger" : ""}" type="submit">Simpan keputusan</button></div></form>`); }
    if (action.dataset.action === "reset-demo") openModal("Reset data demo?", `<div class="demo-warning"><span>ⓘ</span><div>Reset menghapus perubahan demo yang tersimpan di browser ini dan mengembalikan 20 siswa contoh.</div></div><form data-form="reset-demo-confirm"><button class="button button-danger" type="submit">Reset Demo Data</button></form>`);
    if (action.dataset.action === "print-receipt") { document.body.classList.add("printing-receipt"); window.print(); document.body.classList.remove("printing-receipt"); }
  } catch (error) { notify(error.message || "Aksi demo tidak dapat diproses.", true); }
});

document.addEventListener("input", event => {
  if (event.target.id === "student-search") { query = event.target.value; const at = event.target.selectionStart; render(); const input = document.querySelector("#student-search"); input?.focus(); input?.setSelectionRange(at, at); }
});
document.addEventListener("change", event => { if (event.target.id === "period-select") { invoicePeriod = event.target.value; render(); } if (event.target.id === "class-filter") { classFilter = event.target.value; render(); } });
document.addEventListener("submit", event => {
  const form = event.target.closest("form[data-form]"); if (!form) return; event.preventDefault(); const data = new FormData(form);
  try {
    if (form.dataset.form === "student-contact") { state = updateContact(state, { email: data.get("email"), phone: data.get("phone") }); save(); render(); notify("Kontak demo tersimpan di browser ini."); }
    if (form.dataset.form === "create-student") { state = createStudent(state, { name: data.get("name"), nis: data.get("nis"), className: data.get("className") }); save(); render(); notify("Siswa fiktif ditambahkan."); }
    if (form.dataset.form === "fee-rate") { state = updateFeeRate(state, data.get("className"), Number(data.get("amount"))); save(); render(); notify("Tarif demo diperbarui. Invoice lama tidak berubah."); }
    if (form.dataset.form === "discount") { state = addDiscount(state, { label: data.get("label"), className: data.get("className"), amount: Number(data.get("amount")) }); save(); render(); notify("Penyesuaian demo ditambahkan untuk tagihan berikutnya."); }
    if (form.dataset.form === "student-payment") { state = submitDemoPayment(state, data.get("invoiceId"), Number(data.get("amount")), data.get("note")); save(); render(); notify("Pembayaran demo dicatat dan menunggu verifikasi Tata Usaha."); }
    if (form.dataset.form === "payment-decision") { state = decidePayment(state, data.get("paymentId"), data.get("decision"), data.get("reason")); save(); render(); notify("Status pembayaran demo diperbarui."); }
    if (form.dataset.form === "approval-decision") { const next = decideApproval(state, data.get("requestId"), data.get("decision"), data.get("reason"), data.getAll("fields")); const result = next.approvals.find(x => x.id === data.get("requestId")); state = next; save(); render(); notify(`Approval ${statusText(result.status).toLowerCase()}. Diterima: ${result.acceptedFields.join(", ") || "tidak ada"}; bagian lainnya ditolak.`); }
    if (form.dataset.form === "reset-demo-confirm") { state = seedDemo(); prefs = { role: "admin", section: "overview" }; query = ""; classFilter = ""; save(); render(); notify("Data demo browser ini direset."); }
    if (form.dataset.form === "partial-payment") { state = recordPartialPayment(state, data.get("invoiceId"), Number(data.get("amount")), data.get("note")); save(); render(); notify("Pembayaran parsial demo berhasil dicatat."); }
    if (form.dataset.form === "approval-request") { state = requestApproval(state, data.get("invoiceId"), Number(data.get("amount")), data.get("reason")); save(); render(); notify("Permintaan perubahan dikirim ke antrean Admin demo."); }
    if (form.dataset.form === "school-settings") { state = { ...state, school: { ...state.school, name: String(data.get("name")).trim(), tagline: String(data.get("tagline")).trim(), address: String(data.get("address")).trim(), email: String(data.get("email")).trim(), phone: String(data.get("phone")).trim(), academicYear: String(data.get("academicYear")).trim() } }; save(); render(); notify("Identitas placeholder diperbarui di browser ini."); }
    if (form.dataset.form === "contact-message") { notify(`Terima kasih, ${String(data.get("name")).trim()}. Pesan ini hanya simulasi dan tidak dikirim.`); form.reset(); }
  } catch (error) { notify(error.message || "Form demo belum dapat disimpan.", true); }
});
document.querySelector(".menu-toggle")?.addEventListener("click", event => { const nav = document.querySelector(".public-nav"); nav.classList.toggle("open"); event.currentTarget.setAttribute("aria-expanded", String(nav.classList.contains("open"))); });
window.addEventListener("hashchange", () => { render(); window.scrollTo(0, 0); });
if (remoteStorage) {
  main.innerHTML = '<div class="loading-state" role="status">Menghubungkan database demo…</div>';
  loadRemoteState().then(render).catch(() => { remoteReady = false; render(); notify("Database Render belum tersedia. Data belum dapat disinkronkan.", true); });
} else render();
